CommandOutput <pre><code>kelora -j examples/simple_json.jsonl \
    --exec 'e.severity = if e.level == "ERROR" || e.level == "CRITICAL" {
                "high"
            } else if e.level == "WARN" {
                "medium"
            } else {
                "low"
            }' \
    -k level,severity,service,message \
    --take 5
</code></pre> <pre><code>kelora -j examples/simple_json.jsonl \
